    def manual_text(self) -> str:
        """读说明书；没有就写一份模板（只写一次，之后不再覆盖用户改过的）。"""

        path = self.manual_path()
        try:
            if not path.is_file():
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(self.MANUAL_DEFAULT, encoding="utf-8")
            body = path.read_text(encoding="utf-8", errors="replace")
            # 用户 m12215：老版本把这份文件写成了"做人底线"，用途不对；原样没改过的换掉
            if VirtualWorldEngine._is_legacy_manual(body):
                path.write_text(self.MANUAL_DEFAULT, encoding="utf-8")
                return self.MANUAL_DEFAULT
            # 用户 m14211：新版把「边界」那条与「你的处境」重复的罗列删了；
            # 原样没改过的旧模板跟着换，改过的一个字不动。
            if "### 边界（这些不是害羞，是真的做不到）" in body:
                path.write_text(self.MANUAL_DEFAULT, encoding="utf-8")
                return self.MANUAL_DEFAULT
            # 用户 m36545：上一版模板把她写成「跑在插件里的 AI」。原样没改过的跟着换，
            # 用户手写过的（哪怕只改一个字）一个字不动。
            plugin_doc = str(getattr(self, "MANUAL_PLUGIN_DOC", "") or "")
            if plugin_doc and body.strip() == plugin_doc.strip():
                path.write_text(self.MANUAL_DEFAULT, encoding="utf-8")
                return self.MANUAL_DEFAULT
            return body
        except OSError as exc:
            self._log("debug", f"说明书读不出来（不影响这一轮）：{exc}")
            return ""

